package com.khanh.fooddelivery.driver_service.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.oauth2.core.*; import org.springframework.security.web.SecurityFilterChain; import org.springframework.beans.factory.annotation.Value;
@Configuration public class SecurityConfig { @Bean SecurityFilterChain security(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/actuator/info").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(Customizer.withDefaults())).build();} @Bean JwtDecoder jwtDecoder(@Value("${security.jwt.jwk-set-uri:${spring.security.oauth2.resourceserver.jwt.jwk-set-uri:}}") String jwks,@Value("${spring.security.oauth2.resourceserver.jwt.issuer-uri}") String issuer,@Value("${security.jwt.audience}") String audience){NimbusJwtDecoder d=NimbusJwtDecoder.withJwkSetUri(jwks).build(); OAuth2TokenValidator<Jwt> aud=t->t.getAudience().contains(audience)?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token"));d.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer(issuer),aud));return d;} }
